import serial
import time
import signal
import sys

# Configuration
SERIAL_PORT = '/dev/serial0'  # Adjust this to your specific UART port
BAUD_RATE = 9600
TIMEOUT = 2  # Seconds to wait for a response

def setup_serial():
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        sys.exit(1)

def is_valid_reading(reading):
    # Implement your validity check here
    # For example, check if the reading is a number between 0 and 100
    try:
        value = float(reading)
        return 0 <= value <= 100
    except ValueError:
        return False

def read_from_device(ser):
    try:
        ser.write(b'GET_DATA\n')  # Send command to device
        response = ser.readline().decode('utf-8').strip()
        if is_valid_reading(response):
            print(f"Valid reading: {response}")
        else:
            print(f"Invalid reading: {response}")
            sys.exit(1)
    except serial.SerialException as e:
        print(f"Error reading from device: {e}")
        sys.exit(1)

def cleanup(ser, signum, frame):
    if ser.is_open:
        ser.close()
    print("\nProgram terminated.")
    sys.exit(0)

def main():
    ser = setup_serial()

    # Register cleanup function for interrupts and exits
    signal.signal(signal.SIGINT, lambda signum, frame: cleanup(ser, signum, frame))
    signal.signal(signal.SIGTERM, lambda signum, frame: cleanup(ser, signum, frame))

    try:
        read_from_device(ser)
    finally:
        cleanup(ser, None, None)

if __name__ == "__main__":
    main()

